import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
public class FieldJvmCheck implements Opcodes {
 static final String BASE="minecrafttransportsimulator/entities/components/AEntityE_Interactable",VEH="minecrafttransportsimulator/entities/instances/EntityVehicleF_Physics",PART="minecrafttransportsimulator/entities/instances/PartEngine",VAR="minecrafttransportsimulator/baseclasses/ComputedVariable";
 static class Loader extends ClassLoader {Loader(){super(null);}Class<?> add(String name,byte[] data){return defineClass(name.replace('/','.'),data,0,data.length);}}
 static byte[] type(String name,String parent,String field,String desc){ClassWriter w=new ClassWriter(0);w.visit(V21,ACC_PUBLIC|ACC_SUPER,name,null,parent,null);if(field!=null)w.visitField(ACC_PUBLIC,field,desc,null,null).visitEnd();MethodVisitor m=w.visitMethod(ACC_PUBLIC,"<init>","()V",null,null);m.visitCode();m.visitVarInsn(ALOAD,0);m.visitMethodInsn(INVOKESPECIAL,parent,"<init>","()V",false);m.visitInsn(RETURN);m.visitMaxs(1,1);m.visitEnd();w.visitEnd();return w.toByteArray();}
 static byte[] probe(String owner){ClassWriter w=new ClassWriter(0);w.visit(V21,ACC_PUBLIC,"Probe",null,"java/lang/Object",null);MethodVisitor m=w.visitMethod(ACC_PUBLIC|ACC_STATIC,"read","(L"+BASE+";)D",null,null);m.visitCode();m.visitVarInsn(ALOAD,0);m.visitFieldInsn(GETFIELD,owner,"damageVar","L"+VAR+";");m.visitFieldInsn(GETFIELD,VAR,"currentValue","D");m.visitInsn(DRETURN);m.visitMaxs(2,1);m.visitEnd();w.visitEnd();return w.toByteArray();}
 static boolean verify(String owner)throws Exception {Loader l=new Loader();Class<?> var=l.add(VAR,type(VAR,"java/lang/Object","currentValue","D")),base=l.add(BASE,type(BASE,"java/lang/Object","damageVar","L"+VAR+";")),vehicle=l.add(VEH,type(VEH,BASE,null,null)),part=l.add(PART,type(PART,BASE,null,null));try{Class<?> p=l.add("Probe",probe(owner));var m=p.getMethod("read",base);for(Class<?> c:new Class[]{base,vehicle,part}){Object e=c.getConstructor().newInstance(),v=var.getConstructor().newInstance();var.getField("currentValue").setDouble(v,42);base.getField("damageVar").set(e,v);if(((Number)m.invoke(null,e)).doubleValue()!=42)throw new AssertionError("wrong field value");}return true;}catch(VerifyError expected){return false;}}
 public static void main(String[] a)throws Exception {String owner=null;try(ZipFile z=new ZipFile(a[0])){ClassNode c=new ClassNode();new ClassReader(z.getInputStream(z.getEntry("minecrafttransportsimulator/items/instances/ItemItem.class")).readAllBytes()).accept(c,0);for(MethodNode m:c.methods)if(m.name.equals("doEntityInteraction"))for(AbstractInsnNode n:m.instructions.toArray())if(n instanceof FieldInsnNode f&&f.name.equals("damageVar")&&n.getPrevious() instanceof VarInsnNode v&&v.var==1&&n.getNext() instanceof FieldInsnNode next&&next.name.equals("currentValue")&&next.getNext() instanceof VarInsnNode d&&d.getOpcode()==DLOAD)owner=f.owner;}
 if(owner==null)throw new AssertionError("repair comparison missing");if(verify(VEH))throw new AssertionError("must reproduce old JVM VerifyError");if(!verify(owner))throw new AssertionError("repair field owner fails JVM verifier: "+owner);System.out.println("JVM verifier: old vehicle owner rejected; repaired instruction works for base, vehicle and engine receivers");}
}
